INSERT INTO tomes (numero_tomes , id_arc , id_manga , image_tomes , synopsis_tomes) VALUE
-- Manga ---
	(1,1,1, "../img/SwordArtOnline/AincradT1.jpg" , 'En 2022, Kirito, un adolescent sans histoire, se retrouve piégé avec 10 000 autres joueurs dans un jeu en réalité augmentée massivement multijoueurs : Sword Art Online. Pour regagner leur liberté, les joueurs devront compléter les 100 étages qui composent l''Aincrad, leur prison virtuelle. Mais le moindre faux pas pourrait être fatal, puisqu''un Game Over dans le jeu entraînera une mort réelle. Kirito, le joueur solo, se lance dans une course effrénée pour sa survie, dans un monde où l''art de l''épée dicte la loi des plus forts.'),
    (2,1,1, "../img/SwordArtOnline/AincradT2.jpg" , '« Vous êtes bien dans un jeu vidéo, mais vous n''êtes plus là pour jouer. ». Deux ans après le début de la partie, seulement six mille survivants... Kirito est l''un d''eux. Il a décidé de conquérir en « solo » les cent étages qui le mèneront au combat final et qui lui permettra de regagner sa liberté. Mais c''est sans compter sur l''obstination d''Asuna, une habile épéiste avec qui il va devoir s''allier. Démarre alors une course effrénée pour survivre dans un monde où l''art de l''épée dicte la loi. Fin du premier chapitre Aincrad de Sword Art Online.'),
    
    (1,2,1, "../img/SwordArtOnline/FairyDanceT1.jpg" , 'Kazuto Kirigaya, alias Kirito, est revenu sain et sauf d''Aincrad, mais Asuna ne s''est toujours pas réveillée de son coma. Alors qu''il lui rend visite à l''hôpital, il apprend que Nobuyuki Sugô compte l''épouser malgré son état. Peu après, Agil lui montre l''image troublante d''un avatar ressemblant étrangement à Asuna, apparemment prisonnière d''un nouveau VRMMO : ALfheim Online. Convaincu qu''il s''agit bien d''elle, Kirito décide de replonger dans la réalité virtuelle pour la retrouver et découvrir ce qui se cache derrière ce nouveau jeu.'),
	(2,2,1, "../img/SwordArtOnline/FairyDanceT2.jpg" , 'Kirito s''engouffre à l''intérieur du VRMMO « Alfheim Online » pour atteindre le sommet de l''Arbre du monde. Il y rencontre une Sylphide du nom de Leafa, qui accepte de l''y accompagner... Cependant, Leafa n''est en réalité, rien d''autre que la propre sœur de Kazuto, Suguha. Cette dernière éprouve secrètement des sentiments pour celui. Ils poursuivent leur route ensemble vers l'' « Arbre du monde » sans connaître le destin qui les lie, ni celui qui les attend...'),
	(3,2,1, "../img/SwordArtOnline/FairyDanceT3.jpg" , 'Kirito, Yui et Lyfa arrivent au pied de l''Arbre du Monde où est retenue Asuna. Yui ressantant fortement l''ID d''Asuna en haut de l''arbre, elle en informe Kirito. Celui-ci, plus résolu que jamais à sauver Asuna, se lance alors seul à l''assaut de la Grande Quête, que personne n''a jamais réussi à accomplir, mais qui constitue le seul moyen de se rendre au sommet de l''arbre.'),	
    
    (1,3,1, "../img/SwordArtOnline/PhantomBulletT1.jpg" , 'Le volume débute sur un bref rappel des événements de l''arc Aincrad avant de nous plonger directement dans l''univers de GGO via Sinon. Le tournoi du jeu, Bullet of Bullets, est sur le point de débuter lorsqu''un des favoris, Zexceed, disparaît mystérieusement. D''après certains témoins, un étrange individu lui aurait tiré dessus à travers un écran en prétendant le tuer dans la vraie vie. Coïncidence troublante, Zexceed s''est déconnecté peu après, en pleine interview. Kirito est alors choisit par Kikuoka Seijirô pour mener l''enquête de l''intérieur.'),
	(2,3,1, "../img/SwordArtOnline/PhantomBulletT2.jpg" , 'Afin de mener l''enquête qui lui a été confié, Kirito a converti son avatar afin de pouvoir jouer à GGO. Une fois dans le jeu, il a fait la connaissance de Sinon, qui lui a indiqué comment s''inscrire au tournoi. En effet, Kirito est persuadé que Death Gun va profiter du tournoi pour faire de nouvelles victimes et il compte bien l''arrêter avant.'),
    (3,3,1, "../img/SwordArtOnline/PhantomBulletT3.jpg" , 'Alors que la fin du tournoi Bullet of Bullets approche, Kirito et Sinon se trouvent face au mystérieux assassin qui, comme le jeune épéiste, s''avère être un survivant de SAO.'),
    (4,3,1, "../img/SwordArtOnline/PhantomBulletT4.jpg" , 'Kirito a désormais la conviction que Death Gun ne tue pas directement les joueurs dans le jeu, mais qu''il utilise une autre méthode. Ayant l''intuition que Sinon est en danger, il se précipite au secours de cette dernière.'),
    
	(1,4,1, "../img/SwordArtOnline/Calibur.jpg" , 'Après avoir résolu l''affaire "Death Gun", Kirito retourne sur ALO afin d''obtenir l''épée la plus puissante du jeu : la légendaire Excalibur. Accompagné d''Asuna, Klein, Lisbeth, Lyfa, Silica et Sinon, qui s''est créée un avatar pour pouvoir jouer avec le groupe, il se lance donc dans une série de quête basées sur la mythologie nordique.'),
    
    (1,5,1, "../img/SwordArtOnline/MothersRosarioT1.jpg" , 'Depuis quelques temps, un spriggan surnommé Zekken (épée absolue) fait beaucoup parler de lui sur ALO. En effet, ce joueur serait invincible et même Kirito ne serait pas parvenu à le vaincre. Cela pique l''intérêt d''Asuna qui décide de tenter sa chance. C''est ainsi qu''elle rencontre Yuuki, une jeune fille qui lui rappelle beaucoup Kirito et qui, derrière d''impressionnantes capacités, cache un lourd secret.'),
    (2,5,1, "../img/SwordArtOnline/MothersRosarioT2.jpg" , 'Asuna a temporairement rejoint la guilde de Yuuki, les Sleeping Knight, et a entrepris de les aider à accomplir leur objectif : vaincre un boss avec seulement 7 personnes, afin de graver tous leurs pseudonymes sur le Kenshi no Hi, le Mur des Épéistes.'),
    (3,5,1, "../img/SwordArtOnline/MothersRosarioT3.jpg" , 'Alors qu''elle découvre le secret de Yûki, Asuna décide de s''impliquer de plus en plus auprès de la jeune fille et de l''aider à réaliser ses rêves.'),

	(1,6,1, "../img/SwordArtOnline/OrdinalScaleT1.jpg" , 'Ordinal Scale est le jeu le plus populaire auquel il est possible de jouer grâce à l''Augma. Asuna, Klein et leurs amis en sont fans et adorent participer aux events. Kirito, de son côté, est plus réservé. Il faut dire qu''OS est beaucoup plus physique que les autres VRMMORPG et il manque cruellement d''entraînement.'),
	(2,6,1, "../img/SwordArtOnline/OrdinalScaleT2.jpg" , 'Alors qu''elle participe à un événement d''Ordinal Scale proposant de combattre d''anciens boss issus de SAO, Asuna perd subitement la mémoire ! Elle se souvient de sa famille, de ses amis, de sa relation avec Kirito, mais elle a tout oublié des deux années passées dans le jeu mortel. Intrigué, Kirito décide d''enquêter.'),
	(3,6,1, "../img/SwordArtOnline/OrdinalScaleT3.jpg" , 'Après avoir joué à Ordinal Scale un peu plus sérieusement, Kirito découvre les raisons de l''amnésie d''Asuna ainsi que l''objectif d''Eiji et de son complice. Il décide alors d''intervenir pour que ses amis retrouvent leurs souvenirs.'),
	(4,6,1, "../img/SwordArtOnline/OrdinalScaleT4.jpg" , 'Tout ce qui se passe d''étrange dans Ordinal Scale semble lié à la mystérieuse AI Yuna, dont le premier grand concert aura lieu prochainement. Kirito décide de s''y rendre afin de mettre un terme aux ambitions d''Eiji et de ses complices.'),
	(5,6,1, "../img/SwordArtOnline/OrdinalScaleT5.jpg" , 'Le mystérieux lien entre Yuna et Eiji se dévoile, tout comme le but réel du créateur d''Ordinal Scale. Mais est-il encore possible de l''arrêter?'),
    
	(1,7,1, "../img/SwordArtOnline/ProjectAlicizationT1.jpg" , 'Invité à tester une nouvelle machine de réalité virtuelle, Kirito est agressé par un ancien membre de Laughing Coffin et se retrouve piégé dans un mystérieux monde appelé l''Underworld. Incapable de rejoindre la réalité, il y rencontre Eugeo, un jeune entailleur marqué par la disparition de son amie d''enfance, Alice. Ensemble, ils partent dans une quête qui les mènera bien au-delà de leur village. Mais quels secrets cache l''Underworld, et que se trame-t-il dans le monde réel ? La plus grande aventure de l''Épéiste noir ne fait que commencer.'),
    (2,7,1, "../img/SwordArtOnline/ProjectAlicizationT2.jpg" , 'Après avoir été agressé, Kirito s''éveille dans l''Underworld sans vraiment comprendre ce qui lui est arrivé. Là, il retrouve Eugeo, qui a désormais son âge mais ne se souvient pas de lui.'),
    (3,7,1, "../img/SwordArtOnline/ProjectAlicizationT3.jpg" , 'Après s''être fait quelques frayeurs, Kirito et Eugeo ont enfin réussi à venir à bout de la Tâche de ce dernier. Ils peuvent désormais quitter le village et partir à la recherche d''Alice.'),
    (4,7,1, "../img/SwordArtOnline/ProjectAlicizationT4.jpg" , 'Arrêtés par nulle autre qu''Alice, Kirito et Eugeo sont emmenés à la cathédrale où réside l''Administrateur et l''élite de l''empire humain : les Chevaliers Intègres.'),
    (5,7,1, "../img/SwordArtOnline/ProjectAlicizationT5.jpg" , 'Afin de comprendre ce qui est arrivé à Alice, Kirito et Eugeo s''infiltrent au cœur de la cathédrale afin de trouver l''Administrateur. Mais l''ascension est semée d''embûches et le duo doit affronter de nombreux Chevaliers Intègres.'),
    
-- Light Novel ---
	(1,8,2, "../img/SwordArtOnline/L1.jpg" , 'Un « Game Over » entraîne une mort réelle. Piégés dans **Sword Art Online**, un jeu virtuel où chaque erreur peut être fatale, des milliers de joueurs doivent gravir les 100 étages d’**Aincrad** pour retrouver leur liberté. **Kirito**, qui a choisi de combattre seul, voit son destin bouleversé lorsqu’il rencontre **Asuna**, une talentueuse épéiste avec qui il devra s’allier. Commence alors une lutte acharnée pour survivre dans ce monde où l’art de l’épée fait loi.'),
	(2,8,2, "../img/SwordArtOnline/L2.jpg" , 'Après avoir survécu à **Aincrad**, **Kirito** retrouve le monde réel, mais **Asuna** reste plongée dans le coma. Lors d’une visite à l’hôpital, il apprend que **Nobuyuki Sugô** compte épouser Asuna malgré son état. Peu après, **Agil** lui révèle qu’un avatar ressemblant à Asuna serait prisonnier d’un nouveau VRMMO : **ALfheim Online**. Déterminé à la retrouver, Kirito se lance dans une nouvelle aventure.'),
	(3,8,2, "../img/SwordArtOnline/L3.jpg" , 'Un an après son retour dans la réalité, Kazuto Kirigaya, connu sous le pseudonyme de « Kirito, l''épéiste noir », se voit confier une mission dans le nouveau VRMMO à la mode, Gun Gale Online, pour enquêter sur la mort réelle de joueurs tués virtuellement à l''intérieur du jeu. Il y rencontre Shinon, une mystérieuse jeune fille déterminée à remporter le fameux tournoi Bullet of Bullets, battle royale qui déterminera le meilleur joueur de GGO. S''amorce alors pour Kirito, équipé d''un sabre laser, et Shinon la snipeuse, une chasse à l''homme mortelle dans ce monde où les révolvers ont remplacé les épées.'),
	(4,8,2, "../img/SwordArtOnline/L4.jpg" , 'Malgré tous les obstacles qu''il a surmonté avec brio, Kirito perd un combat face au mystérieux joueur « l''Épée Absolue ». Intriguée par cette défaite, Asuna décide d''aller à la rencontre de cet individu, qui se révèle être une jeune fille nommée Yûki. Après avoir fait la connaissance de sa guilde, les Sleeping Knights, Asuna s''allie au petit groupe afin de les aider à terminer une quête. Durant cette nouvelle aventure, elle va découvrir un terrible secret qui la marquera à jamais. Une aventure humaine qui dépasse le virtuel.`},'),
	(5,8,2, "../img/SwordArtOnline/L5.jpg" , '**Kirito** se réveille dans l’*Underworld*, un mystérieux monde virtuel dont il ne peut s’échapper. Il y rencontre **Eugeo**, un jeune villageois hanté par la disparition de son amie d’enfance, **Alice**. Ensemble, ils partent en quête de réponses, découvrant peu à peu les secrets de l’*Underworld*, des mystérieux **Chevaliers Intègres** et du *Monde des Hommes*. Mais dans la réalité aussi, une menace se prépare. L’épopée de l’**Épéiste Noir** ne fait que commencer. Bienvenue dans le projet ***Alicization***.`},'),
	(6,8,2, "../img/SwordArtOnline/L6.jpg" , 'Kirito et Eugeo sont désormais en deuxième année à l''école des épéistes et comptent parmi les meilleurs élèves de l''établissement. Mais en essayant d''aider le valet d''un autre épéiste, ils brisent un tabou et sont arrêtés par Alice, qui est devenu une Seigô Kishi (Integrity Knight).`},'),
	(7,8,2, "../img/SwordArtOnline/L7.jpg" , 'En pleine ascension de l''immense tour blanche, bastion de l''Église de l''Axiome et demeure des Chevaliers Intègres, Kirito et Eugeo se retrouvent brutalement séparés. Propulsé hors des murs de la Cathédrale, Kirito accompagne le Chevalier Alice Synthesis Thirty dans une chute vertigineuse. Désormais seul, Eugeo doit gravir les derniers étages et déjouer les redoutables pièges de la tour afin d''affronter son ennemi juré : l''archevêque Administrator. Mais alors que la quête semble arriver à son terme, les deux jeunes épéistes se voient obligés de subir la plus effroyable des épreuves.'),
	(8,8,2, "../img/SwordArtOnline/L8.jpg" , 'Après la défaite d’**Administrator**, le *Monde des Hommes* est enfin libéré, mais **Kirito** reste plongé dans sa propre conscience, incapable de parler. **Alice** retourne à *Rulid* pour trouver un moyen de le sauver. Dans la réalité, l’*Ocean Turtle* est attaqué par des mercenaires menés par **Gabriel Miller**, déterminé à s’emparer de l’âme d’**Alice**, l’Intelligence Artificielle parfaite. La Guerre de l’*Underworld* commence'),
	(9,8,2, "../img/SwordArtOnline/L9.jpg" , 'Déterminé à kidnapper **Alice**, l’Intelligence Artificielle parfaite, **Gabriel Miller**, alias **Vector**, rassemble une armée de joueurs américains, chinois et coréens. **Asuna**, résolue à protéger **Kirito**, lutte aux côtés de l’armée de l’*Underworld*. Alors que la situation devient critique, **Sinon** et **Leafa** apparaissent sous les traits des déesses Solus et Terraria. Dans la réalité, **Lisbeth**, **Klein**, **Agil** et **Silica** mobilisent des milliers de joueurs pour venir en aide aux habitants de l’*Underworld*. Le grand final de l’arc **Alicization** !'),
	(10,8,2, "../img/SwordArtOnline/L10.jpg" , 'Deux cents ans avant le retour de **Kirito**, **Asuna** et **Alice** dans l’*Underworld*, la paix entre le Monde des Hommes et le Pays des Ténèbres est menacée. **Lonie Arabel**, apprentie Chevalier Intègre, et **Kirito**, représentant des bretteurs, enquêtent sur un meurtre à *Centoria*. Leur quête les mènera aux confins des terres connues, entre complots, créatures mystérieuses et sombres desseins, pour empêcher une nouvelle guerre d’éclater.'),
	(11,8,2, "../img/SwordArtOnline/L11.jpg" , 'Un an s''est écoulé depuis le retour de Kirito et Asuna du monde de l''Underworld. Avec eux se trouve Alice, qui a reçu un corps physique. Mais leur paix est rapidement interrompue lorsque les trois sont soudainement plongés dans un jeu inconnu, Unital Ring. Ce nouveau monde est un MMO de survie qui fusionne tous les VRMMO créés avec le programme Seed. Dès le début, Kirito se retrouve avec seulement ses sous-vêtements. Maintenant, il doit relever le défi de ce mystérieux VRMMOSVG dans des circonstances désespérées !'),
	(12,8,2, "../img/SwordArtOnline/L12.jpg" , 'Sinon, la joueuse de GGO, a également été transportée dans le mystérieux VRMMO Unital Ring. Après de nombreuses péripéties, elle décide de rejoindre Kirito et ses amies, ce qui implique de parcourir des étendues désertes et hostiles avec un équipement rudimentaire. Y parviendra-t-elle avant de mourir de soif ou de se faire tuer par un boss ?'),
	(13,8,2, "../img/SwordArtOnline/L13.jpg" , ''),

	(1,9,2, "../img/SwordArtOnline/J1.jpg" , 'En 2022, une société lance sur le marché le très attendu Sword Art Online, un jeu dans lequel les joueurs se trouvent totalement immergés au moyen d''un casque baptisé NerveGear. Mais une désagréable surprise attend les 10 000 joueurs connectés le jour du lancement : il n''y a pas de bouton de déconnexion et le créateur du jeu leur annonce qu''à partir de ce jour, mourir dans le jeu signifiera mourir dans le monde réel. Pour sortir, une seule solution : terminer le jeu.'),
	(2,9,2, "../img/SwordArtOnline/J2.jpg" , 'Ce tome contient 4 histoires se déroulant durant l''arc Aincrad.'),
	(3,9,2, "../img/SwordArtOnline/J3.jpg" , 'L''Aincrad a disparu et Kirito s''est enfin réveillé. Mais alors qu''il réapprend à vivre dans le monde réel, il apprend qu''Asuna et 300 autres joueurs ne se sont toujours pas réveillés. Plus tard, Agil lui montre la photo d''une jeune femme ressemblant fortement à Asuna, qui aurait été prise dans un nouveau jeu : ALfheim Online. Kirito prend alors le risque de réutiliser son NerveGear pour la retrouver.'),
	(4,9,2, "../img/SwordArtOnline/J4.jpg" , 'En chemin vers Yggdrasil, Kirito et Leafa sont avalés par un gigantesque ver de terre et sont envoyés à Jötunheimr. Ils vont alors tenter de trouver un chemin pour retourner au plus vite à la surface, car le temps presse. Dans le même temps, Asuna a enfin réussi à mémoriser le code qui ouvre sa cage et s''évade.'),
	(5,9,2, "../img/SwordArtOnline/J5.jpg" , 'Un an après sa victoire sur Akihiko Kayaba, Kazuto Kirigaya (Kirito) est contacté par Seijirô Kikuoka pour enquêter sur d''étranges événements survenus dans le jeu Gun Gale Online. En effet, un joueur se faisant appeler Death Gun aurait réellement tué une personne en lui tirant dessus dans le jeu.'),
	(6,9,2, "../img/SwordArtOnline/J6.jpg" , 'Pour démasquer Death Gun, Kirito participe au grand tournoi de Gun Gale Online, Bullet of Bullets. Pour avoir plus de chances de réussir sa mission, il demande à Sinon, qui s''est elle aussi qualifiée, de lui accorder son aide.'),
	(7,9,2, "../img/SwordArtOnline/J7.jpg" , 'Dans ALO, un mystérieux joueur surnommé Zekken propose de donner son OSS (Original Sword Skill) exceptionnel de onze coups à qui parviendra à le battre. Kirito a relevé le défi mais a perdu, ce qui intrigue Asuna. Elle décide donc de se mesurer elle aussi à Zekken et fait ainsi la connaissance de Yûki, une joueuse dont elle va rapidement devenir très proche.'),
	(8,9,2, "../img/SwordArtOnline/J8.jpg" , 'Ce tome contient deux histoires se déroulant dans l''univers d''Aincrad (A Murder Case in the Area et First Day) ainsi qu''une histoire se déroulant dans l''univers d''ALfheim Online (Caliber).'),
	(9,9,2, "../img/SwordArtOnline/J9.jpg" , 'Kirito a trouvé un travail à mi-temps en rapport avec une toute nouvelle machine permettant de s''immerger dans une réalité alternative. Ce tout nouveau projet est lié au monde d''Alice au Pays des Merveilles, mais il est encore confidentiel. Un jour, alors qu''il raccompagne Asuna, Kirito est attaqué par un ancien membre de la guilde Laughing Coffin, qui parvient à lui injecter une dose de succinylcholine. Entre la vie et la mort, il est amené dans un centre de recherche où son esprit est relié au monde d''Alice afin de lui donner l''opportunité de guérir.'),
	(10,9,2, "../img/SwordArtOnline/J10.jpg" , 'Kazuto ayant mystérieusement disparu suite à son transfert entre deux hôpitaux, Asuna tente vainement de le retrouver grâce à l''aide de Yui et de Rinko Kôjiro, l''ancienne petite amie d''Akihiko Kayaba. De son côté, Kirito a déjà passé 2 ans dans l''Underworld (environ 18 heures du monde réel) et est entré dans une école qui forme les épéistes avec son ami Eugeo.'),
	(11,9,2, "../img/SwordArtOnline/J11.jpg" , 'Kirito et Eugeo sont désormais en deuxième année à l''école des épéistes et comptent parmi les meilleurs élèves de l''établissement. Mais en essayant d''aider le valet d''un autre épéiste, ils sont mis dos au mur et n''ont pas d''autre choix que de briser un tabou. Ils sont ensuite arrêtés par Alice, qui est devenue une Seigô Kishi (Integrity Knight).'),
	(12,9,2, "../img/SwordArtOnline/J12.jpg" , 'Cardinal raconte sa propre histoire, ainsi que celle de Quinella, à Kirito. Elle l''avertit également que des monstres menacent les territoires des Hommes et lui propose un marché. Afin de vaincre Quinella, le jeune épéiste accepte.'),
	(13,9,2, "../img/SwordArtOnline/J13.jpg" , 'Kirito et Alice sont tombés du 80ème étage du Central Cathedral mais, par chance, Kirito est parvenu à planter son épée dans une brèche, freinant ainsi leur chute. Malgré tout, les deux compagnons ne sont pas encore tirés d''affaire pour autant. Eugeo, de son côté, poursuit son ascension seul mais il se retrouve nez à nez avec Bercouli, un puissant Integrity Knight.'),
	(14,9,2, "../img/SwordArtOnline/J14.jpg" , 'Eugeo étant devenu un ennemi, Kirito n''a pas d''autre choix que de l''affronter. Dans le même temps, il essaie toutefois de faire resurgir les souvenirs qui ont été dérobés à son ami. Il y parvient après plusieurs tentatives mais trop tard : lui et Alice sont pris dans une attaque de glace et temporairement paralysés.'),
	(15,9,2, "../img/SwordArtOnline/J15.jpg" , 'Kirito est parvenu à vaincre l''Administrateur et à protéger l''Underworld, mais cette victoire a un goût bien amer pour Alice : Eugeo est mort et Kirito n''est plus que l''ombre de lui-même.'),
	(16,9,2, "../img/SwordArtOnline/J16.jpg" , 'Alors que la situation va de mal en pis dans l''Underworld, Ronye et Tiese tentent tant bien que mal de protéger Kirito, toujours dans un état second. Dans le même temps, Asuna décide de se connecter à l''Underworld pour le retrouver.'),
	(17,9,2, "../img/SwordArtOnline/J17.jpg" , 'L''Underworld est désormais totalement plongé dans un chaos indescriptible : la gigantesque armée de Dark God Vector s''oppose violemment à celle d''Alice, gagnant de plus en plus de terrain grâce à une aide inattendue venue du monde réel. De son côté, Asuna tente d''apporter tout son soutien à Alice, mais seule, elle n''est pas de taille. C''est alors qu''elle est rejoint par Leafa et Sinon.'),
	(18,9,2, "../img/SwordArtOnline/J18.jpg" , 'Alors que la situation est de plus en plus critique et qu''Alice est poursuivie par Subtlizer, Asuna et ses compagnons tentent tant bien que mal d''inverser la tendance. Malheureusement, leurs efforts sont vains et Kirito, toujours dans un état second, est capturé par l''ennemi. Mais alors que tout semble perdu, le jeune homme entend une voix qui le pousse à reprendre ses esprits et à se battre pour survivre, et protéger ceux qu''il aime.'),
	(19,9,2, "../img/SwordArtOnline/J19.jpg" , 'Ce tome contient des histoires se déroulant en parallèle et à la suite de l''arc Alicization. L''une d''elle se centre sur Ronie Arabel, qui apprend une vérité choquante de la part de son maître d''arme, Kirito.'),
	(20,9,2, "../img/SwordArtOnline/J20.jpg" , 'À l''instar du tome 19, ce tome contient des histoires se déroulant en parallèle de l''arc Alicization.'),
	(21,9,2, "../img/SwordArtOnline/J21.jpg" , 'Un mois après leur réveil, Kirito et Asuna, accompagnés par Alice, sont entrainés dans le tout nouveau survival game à la mode : Unital Ring. Deux surprises de taille les y attendent : leurs avatars ont régressés au niveau 1 et les jeux issus de "The Seed" semblent avoir fusionné dans ce nouveau monde virtuel.'),
	(22,9,2, "../img/SwordArtOnline/J22.jpg" , 'Ce volume contient quatre histoires indépendantes. Elles ont déjà été publiées sous le titre "Sword Art Online - Side Stories" et distribuées dans les collectors DVD et Blu-ray des différentes saisons de l''anime. Les anecdotes compilées dans ce volume sont "The Day Before" (1.5) ; "The Day After" (4.5) ; Rainbow Bridge (EX) ; Sisters'' Prayer (7.5).'),
	(23,9,2, "../img/SwordArtOnline/J23.jpg" , 'Après Kirito, Asuna et Alice, c''est au tour de Sinon d''être entraînée dans l''univers de Unital Ring. Mais à son arrivée dans ce nouveau monde, elle ne dispose d''aucun moyen pour se défendre et doit donc fuir dans des contrées reculées ! En parallèle, Kirito, visiblement la cible de troupes ennemies, tente tant bien que mal de retrouver Sinon tout en protégeant sa base.'),
	(24,9,2, "../img/SwordArtOnline/J24.jpg" , 'Après avoir à nouveau croisé la route de Seijirô Kikuoka, Kirito, Asuna et Alice sont renvoyés dans l''Underworld. Mais ce dernier a bien changé puisque 200 ans se sont écoulés depuis la guerre. Le trio croise ainsi la route des descendants de Tiese et Ronie ainsi qu''un homme étrange, au regard similaire à celui d''un ami disparu. Pendant ce temps, la situation se détériore dans le monde d''Unital Ring.'),
	(25,9,2, "../img/SwordArtOnline/J25.jpg" , 'Kirito accuse le coup après avoir croisé la route d''Eolyne ; ce dernier lui rappelle bien trop Eugeo et de douloureux souvenirs refont surface. Malheureusement, le jeune Japonais n''a pas le temps de se laisser aller à la nostalgie, car la situation ne cesse de se dégrader dans les deux mondes : Underworld et Unital Ring.'),
	(26,9,2, "../img/SwordArtOnline/J26.jpg" , 'La bataille de Kirito et ses compagnons, englobant deux mondes, entre dans une nouvelle étape !'),
	(27,9,2, "../img/SwordArtOnline/J27.jpg" , 'Alors que Kirito et ses compagnons sont confrontés à de plus en plus de visages familiers, l''ennemi fait surface et ne leur laisse pas le temps de réfléchir. Il est désormais temps de l''affronter.'),
	(28,9,2, "../img/SwordArtOnline/J28.jpg" , 'Peu à peu, les Chevaliers Intègres que Kirito a connu sortent de leur léthargie et se joignent aux combats ; la situation devient de plus en plus chaotique dans l''Underworld. En parallèle, dans le monde réel, Asuna est abordée par une personne qu''elle n''a pas vu depuis un long moment.'),
	(29,9,2, "../img/SwordArtOnline/J29.jpg" , 'Eolyne a été capturé ! Il découvre alors ceux qui se cachent derrière l''invasion et met au point un plan pour s''enfuir. En parallèle, Kirito tente d''avancer dans Unital Ring.'),

-- Progressive ---
	(1,10,3, "../img/SwordArtOnline/P1T1.jpg" ,'Tout comme dix mille autres joueurs, Asuna Yûki est piégée dans la forteresse d''Aincrad au cœur du monde virtuel de Sword Art Online. Complètement inexpérimentée, elle éprouve des difficultés à s''adapter à ce nouvel univers, mais très vite sa volonté farouche de survie la pousse à combattre en première ligne. Elle y rencontre Kirito, un mystérieux joueur solo bien résolu à terminer le jeu. Suivez Asuna et Kirito dans leur conquête de l''Aincrad, étage par étage.'),
	(2,10,3, "../img/SwordArtOnline/P1T2.jpg" ,'Ce deuxième tome se concentre sur le combat contre le premier boss "Illfang the Kobold Lord"'),
	(3,10,3, "../img/SwordArtOnline/P1T3.jpg" ,'Le tome commence avec une Asuna plus déprimée que jamais. En effet, suite à une tentative d''amélioration de sa rapière Wind Fleuret par le forgeron, cette dernière a mystérieusement été détruite au cours de l''opération. Mais Kirito, bien décidé à ne plus jamais voir son "associée" en larme, ne l''entend pas de cette oreille et part enquêter avec l''aide d''Argo.'),
	(4,10,3, "../img/SwordArtOnline/P1T4.jpg" ,'La bataille contre le boss du niveau 2 est sur le point de commencer mais Asuna manque à l''appel, bloquée par une quête secondaire, ce qui semble perturber Kirito. La capacité de paralysie du boss force les joueurs à faire montre d''une extrême prudence rendant le combat plus ardu que prévu.'),
	(5,10,3, "../img/SwordArtOnline/P1T5.jpg" ,''),
	(6,10,3, "../img/SwordArtOnline/P1T6.jpg" ,'Asuna et Kirito continuent leur aventure aux côtés de Kizmel dans ce jeu de la mort au sein de l''Aincrad.'),
	(7,10,3, "../img/SwordArtOnline/P1T7.jpg" ,'Le mystérieux joueur Morte a manipulé les guildes humaines dans le but qu''elles combattent contre les deux camps durant la guerre des Elfes! Pendant que Kirito le défie en duel, Asuna doit accomplir une importante tâche: voler les plans de bataille. Ils doivent mettre fin à la guerre avant que quelqu''un ne perde la vie.'),
   
	(1,11,3, "../img/SwordArtOnline/P2T1.jpg" ,'Après la victoire des Elfes Noirs sur les Elfes Sylvestres avec l''aide de Kizmel, Asuna Yuki, Argo et Kirigaya Kazuto continuent leur périple au cœur du jeu mortel Sword Art Online, tout en atteignant le quatrième pallier du jeu. Asuna et Kirito vont alors pouvoir profiter d''un bref moment de répit dans les vastes lacs du quatrième pallier, mais qui sait quels dangers peuvent les attendre....'),
	(2,11,3, "../img/SwordArtOnline/P2T2.jpg" ,''),

	(1,12,3, "../img/SwordArtOnline/P3T1.jpg" ,'Kirito se voit être défié par sa chère et tendre partenaire : Asuna Yuuki ! Mais ce combat ne se passe pas extrêmement bien pour elle puisqu''elle prend peur si bien que, pour se faire pardonner, Kirito va lui offrir un feu de camp où il lui résumera les évènements passés précédemment. C''est ainsi que débute leur nouvelle aventure au palier 5 !'),
	(2,12,3, "../img/SwordArtOnline/P3T2.jpg" ,'Aprés les évènements du tome 1, nous retrouvons Asuna et Argo discutant d''une certaine méthode de combat dans un bain, et décident d''amicalement s''affronter. À la grande surprise d''Asuna, Argo a plus d''un tour dans sa manche avec sa technique de griffes.'),
	(3,12,3, "../img/SwordArtOnline/P3T3.jpg" ,''),

	(1,13,3, "../img/SwordArtOnline/P4T1.jpg" ,''),
	(2,13,3, "../img/SwordArtOnline/P4T2.jpg" ,''),

-- Progressive LN ---
	(1,null,4, "../img/SwordArtOnline/PL1.jpg" , 'Un mois s''est écoulé depuis que le jeu de la mort Sword Art Online a ouvert ses portes et emprisonné dix mille âmes. Kirito, un joueur solo qui s''est juré de ne penser qu''à son amélioration personnelle, va faire la rencontre d''une figure rare sur les lignes de front : une joueuse. Cette fille qui enchaine les combats contre de redoutables monstres à la seule force de sa rapière a tout d''une étoile filante transperçant le ciel nocturne.'),
	(2,null,4, "../img/SwordArtOnline/PL2.jpg" , 'Ce tome relate la conquête du troisième étage d''Aincrad.'),
	(3,null,4, "../img/SwordArtOnline/PL3.jpg" , 'Après s''être séparés de l''elfe Kizmel, Kirito et Asuna se rendent au 4è étage d''Aincrad mais, à la grande surprise du Beta testeur, cet étage a été totalement modifié : il est désormais majoritairement couvert d''eau !'),
	(4,null,4, "../img/SwordArtOnline/PL4.jpg" , 'Cinquante-deux jours après avoir été piégés dans Sword Art Online, Kirito et Asuna atteignent le cinquième étage d''Aincrad, qui est une zone couverte de ruines, comme dans la version beta. Mais alors qu''ils tentent de compléter une quête dans un cimetière, la malchance les frappe.'),
	(5,null,4, "../img/SwordArtOnline/PL5.jpg" , 'Kirito et Asuna ont atteint le sixième palier, mais entre les énigmes à résoudre pour passer à l''étage supérieur et les potentiels pièges mortels, ils n''ont pas vraiment le temps de profiter de leur victoire précédente. De plus, un groupe de PK a décidé de faire des siennes.'),
	(6,null,4, "../img/SwordArtOnline/PL6.jpg" , 'Toujours bloqués au sixième étage, Kirito et Asuna retrouvent Kizmel, qui leur propose une nouvelle quête.'),
	(7,null,4, "../img/SwordArtOnline/PL7.jpg" , 'Kirito et Asuna ont enfin atteint le 7è étage ! Là, ils sont confrontés à un "donjon" un peu particulier, similaire à un casino.'),
	(8,null,4, "../img/SwordArtOnline/PL8.jpg" , 'Alors que Nirrnir, aidée d''Argo, Asuna et Kirito, est sur le point de révéler la tricherie organisée par la famille Korloy, les évènements prennent une tournure dramatique. Entre la récupération des mystérieuses clés volées par les Déchus, la conquête de l''étage et ce complot diabolique... Les jeunes joueurs n''ont plus un instant à eux. Parviendront-ils à résoudre toutes ces quêtes au degré de difficulté élevé ?'),
	(9,null,4, "../img/SwordArtOnline/PL9.jpg" , 'Après la victoire sur le boss du 7è étage, Kirito, Asuna et Kizmel arrivent au 8è étage où l''épéiste noir devient un vassal vampirique. Il gagne ainsi certains avantages mais aussi une faiblesse fatale face à la lumière du jour.');
    
INSERT INTO saisons (numero_saisons , id_anime , episodes_saisons , nom_saisons , image_saisons , synopsis_saisons) VALUE
-- Série ---
	(1,1,25, 'Saison 1' , '../img/SwordArtOnline/S1.jpg' , 'En 2022, Sword Art Online devient le premier MMORPG utilisant une technologie de réalité virtuelle permettant une immersion totale. Mais dès son lancement, 10 000 joueurs se retrouvent piégés par son créateur, Akihiko Kayaba. Pour retrouver leur liberté, ils devront terminer le jeu, avec une terrible règle : mourir dans SAO signifie mourir dans la réalité. Kirito, ancien bêta-testeur, décide de partir seul à la conquête des 100 étages d''Aincrad et de leurs redoutables boss. Parviendra-t-il à terminer le jeu et à libérer tous les joueurs ?'),
    (2,1,25, 'Saison 2' , '../img/SwordArtOnline/S2.jpg' , 'Après sa victoire face à Sugou Nobuyuki, Kirito retrouve enfin sa paisible vie de lycéen. Mais plusieurs morts mystérieuses viennent bientôt troubler son quotidien : des joueurs de Gun Gale Online seraient décédés dans la réalité après avoir été abattus dans le jeu. Sollicité par Kikuoka Seijirô pour enquêter, Kirito plonge dans ce nouvel univers dominé par les armes à feu. Il devra participer au tournoi Bullet of Bullets et retrouver Death Gun, un mystérieux joueur qui semble capable de tuer ses victimes à travers le monde virtuel.'),
    (3,1,47, 'Saison 3 - Alicization' , '../img/SwordArtOnline/S3.jpg' , 'À la demande de Seijirô Kikuoka, Kazuto teste le Soul Translator, une nouvelle technologie développée par Rath qui lui permet d''accéder à l''Underworld. Il y rencontre Eugeo et Alice, deux enfants avec lesquels il se lie d''amitié, avant qu''Alice ne soit emmenée pour avoir enfreint les lois de ce monde. Plus tard, Kazuto est grièvement blessé dans la réalité par un ancien membre de Laughing Coffin. Pour le sauver, il est plongé dans l''Underworld, où plusieurs années se sont écoulées et où il retrouve Eugeo, désormais devenu un jeune homme.'),
    
-- Offline ---
	(1,6,9, 'Sword Art Offline' , '../img/SwordArtOnline/Off.jpg' , 'Ce sont les épisodes spéciaux de l''anime Sword Art Online. Ils se déroulent comme si c''était une émission de Télé Réalité dans le monde réel. Kirito et Asuna, les présentateurs de l''émission Sword Art Offline, accueillent quelques invités qui leurs racontent certains moments passés dans le jeux vidéo (l''anime).'),
    (2,6,1, 'Extra Edition' , '../img/SwordArtOnline/OffExtra.jpg' , 'Spécial inclus dans le DVD/Blu-ray de Sword Art Online : Extra Edition.'),
    (3,6,9, 'Sword Art Offline II' , '../img/SwordArtOnline/Off2.jpg' , 'Épisodes spéciaux qui seront inclus dans les DVD/Blu-ray de la série Sword Art Online II.'),
    (4,6,1, 'Ordinal Scale' , '../img/SwordArtOnline/OffOS.jpg' , 'Episode spécial inclus dans le DVD/Blu-ray du film Sword Art Online the Movie -Ordinal Scale-.');